import math
n = int(input())
circles = []
for _ in range(n):
    x, y, r = map(int, input().split())
    circles.append({'x': x, 'y': y, 'r': r})

def distance(a, b):
    return math.hypot(a['x'] - b['x'], a['y'] - b['y'])

def is_intersect(a, b):
    d = distance(a, b)
    return d <= a['r'] + b['r'] + 1e-10 and d + 1e-10 >= abs(a['r'] - b['r'])

def is_intersect2(a, b):
    d = distance(a, b)
    return d < a['r'] + b['r'] and d > abs(a['r'] - b['r'])

def intersect_at(a, b, set_points):
    if not is_intersect(a, b):
        return
    line_vector = {'x': b['x'] - a['x'], 'y': b['y'] - a['y']}
    d = distance(a, b)
    midDist = (d * d - b['r'] * b['r'] + a['r'] * a['r']) / (2 * d)
    mid_x = a['x'] + line_vector['x'] * (midDist / d)
    mid_y = a['y'] + line_vector['y'] * (midDist / d)
    mid = {'x': mid_x, 'y': mid_y}
    alpha = {'x': -line_vector['y'], 'y': line_vector['x']}
    h = math.sqrt(max(a['r'] * a['r'] - midDist * midDist, 0))
    def move_along_vector(v, length):
        mag = math.hypot(v['x'], v['y'])
        if mag < 1e-15:
            return {'x': mid['x'], 'y': mid['y']}
        return {'x': mid['x'] + v['x'] / mag * length, 'y': mid['y'] + v['y'] / mag * length}
    p1 = move_along_vector(alpha, h)
    p2 = move_along_vector({'x': -alpha['x'], 'y': -alpha['y']}, h)
    set_points.add((p1['x'], p1['y']))
    if not (abs(p2['x'] - p1['x']) < 1e-10 and abs(p2['y'] - p1['y']) < 1e-10):
        set_points.add((p2['x'], p2['y']))

total = 1
points_set = set()
for i in range(n):
    points_set.clear()
    total += 1
    for j in range(i):
        intersect_at(circles[i], circles[j], points_set)
    if len(points_set) >= 2:
        total += len(points_set) - 1

print(total)

